// Sortable Lite - Drag and Drop for JARVIS Kids OS Games
(function(window) {
  'use strict';
  function Sortable(el, options) {
    this.el = typeof el === 'string' ? document.querySelector(el) : el;
    this.options = options || {};
    this.draggedItem = null;
    this.init();
  }

  Sortable.prototype.init = function() {
    if (!this.el) return;
    var self = this;
    var items = this.el.children;

    for (var i = 0; i < items.length; i++) {
      this.makeDraggable(items[i]);
    }

    this.el.addEventListener('dragover', function(e) {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      var target = e.target.closest(self.options.draggable || '> *');
      if (target && target !== self.draggedItem && target.parentNode === self.el) {
        var rect = target.getBoundingClientRect();
        var next = (e.clientY - rect.top) / (rect.bottom - rect.top) > 0.5;
        self.el.insertBefore(self.draggedItem, next ? target.nextSibling : target);
      }
    });

    this.el.addEventListener('drop', function(e) {
      e.preventDefault();
      if (self.options.onEnd && typeof self.options.onEnd === 'function') {
        self.options.onEnd({ item: self.draggedItem });
      }
    });
  };

  Sortable.prototype.makeDraggable = function(item) {
    var self = this;
    item.setAttribute('draggable', 'true');
    item.style.cursor = 'grab';

    item.addEventListener('dragstart', function(e) {
      self.draggedItem = item;
      e.dataTransfer.effectAllowed = 'move';
      item.style.opacity = '0.5';
    });

    item.addEventListener('dragend', function() {
      item.style.opacity = '1';
      self.draggedItem = null;
    });
  };

  Sortable.create = function(el, options) {
    return new Sortable(el, options);
  };

  window.Sortable = Sortable;
})(window);
